(6964864, 1050756, 12611, '<td valign="top">just a wonderful mood and feeling you have created with the warm glow here.</td>', 'just a wonderful mood and feeling you have created with the warm glow here.', '2013-01-26 11:20:44.000000', NULL, 1),
(6964865, 1050092, 12611, '<td valign="top">great colors.</td>', 'great colors.', '2013-01-26 11:21:36.000000', NULL, 1),
(6964866, 1050714, 12611, '<td valign="top">Great feeling to this shot. A beautiful display of feelings of warmth and cold and the same time, perhaps of longing...</td>', 'Great feeling to this shot. A beautiful display of feelings of warmth and cold and the same time, perhaps of longing...', '2013-01-26 11:22:32.000000', NULL, 1),
(6964867, 1050588, 12611, '<td valign="top">I get the immediate impression of more than physical, a sort of metaphysical light beacon shining from the top of spire out into the village below, a hulking presence, there whether they want it or not. The toned presentation adds a time frame, an antiqued feel that disorients the viewer, as to time. The border is subtla and nice too.</td>', 'I get the immediate impression of more than physical, a sort of metaphysical light beacon shining from the top of spire out into the village below, a hulking presence, there whether they want it or not. The toned presentation adds a time frame, an antiqued feel that disorients the viewer, as to time. The border is subtla and nice too.', '2013-01-26 11:27:11.000000', NULL, 1),
(6964869, 1050717, 12611, '<td valign="top">Really nice textures- they play nicely with the khaki and gray colors. I like the blur of the subjects in motion, a good feeling of movement.</td>', 'Really nice textures- they play nicely with the khaki and gray colors. I like the blur of the subjects in motion, a good feeling of movement.', '2013-01-26 11:28:25.000000', NULL, 1),
(6964870, 1050862, 12611, '<td valign="top">a nice, pbs tv series style look at a near-steampunk shot/ the shoelessness is a nice touch.</td>', 'a nice, pbs tv series style look at a near-steampunk shot/ the shoelessness is a nice touch.', '2013-01-26 11:33:37.000000', NULL, 1),
(6964875, 1050825, 12611, '<td valign="top">Nice processing and muted tones. I actually like the foreground detail very much.</td>', 'Nice processing and muted tones. I actually like the foreground detail very much.', '2013-01-26 11:36:48.000000', NULL, 1),
(6964877, 1050551, 12611, '<td valign="top">Super slick processing, almost graphic novel. Its quite a nice shot.</td>', 'Super slick processing, almost graphic novel. Its quite a nice shot.', '2013-01-26 11:37:38.000000', NULL, 1),
(6964921, 1050373, 140537, '<td valign="top">I really like the composition and processing. Just wish that sink wasn''t there. Distracting. <br/>You should have hired a plumber to remove it before taking this shot. ;-)</td>', 'I really like the composition and processing. Just wish that sink wasn''t there. Distracting. You should have hired a plumber to remove it before taking this shot. ;-)', '2013-01-26 12:44:56.000000', NULL, 1),
(6964925, 1050814, 140537, '<td valign="top">Great shot. Can''t decide if I would have preferred this without the person or not. <br/>Love the lines/composition. I think it would be better without the blown highlights in the window. Like the shading on the walls. <br/>Well done.</td>', 'Great shot. Can''t decide if I would have preferred this without the person or not. Love the lines/composition. I think it would be better without the blown highlights in the window. Like the shading on the walls. Well done.', '2013-01-26 12:49:06.000000', NULL, 1),
(6965094, 1050735, 112539, '<td valign="top">I don''t get where the from on high challenge comes in here.</td>', 'I don''t get where the from on high challenge comes in here.', '2013-01-26 21:02:51.000000', NULL, 1),
(6965098, 1050110, 23484, '<td valign="top">I love the angle.</td>', 'I love the angle.', '2013-01-26 21:19:32.000000', NULL, 1),
