(6966466, 1050379, 16148, '<td valign="top">Complex collection of levels and compartments.   Nice!</td>', 'Complex collection of levels and compartments.   Nice!', '2013-01-29 16:23:35.000000', NULL, 1),
(6966575, 1050588, 114225, '<td valign="top">I like this choice in composition.</td>', 'I like this choice in composition.', '2013-01-29 19:46:00.000000', NULL, 1),
(6966577, 1050373, 114225, '<td valign="top">I enjoy the different patterns on display here.</td>', 'I enjoy the different patterns on display here.', '2013-01-29 19:47:49.000000', NULL, 1),
(6966578, 1050551, 114225, '<td valign="top">Excellent timing.</td>', 'Excellent timing.', '2013-01-29 19:48:12.000000', NULL, 1),
(6966579, 1050819, 114225, '<td valign="top">I like how the smoke offsets the sun. Bt the saturation is way too high for my tastes.</td>', 'I like how the smoke offsets the sun. Bt the saturation is way too high for my tastes.', '2013-01-29 19:48:59.000000', NULL, 1),
(6966580, 1050753, 114225, '<td valign="top">There s something great about this photo.</td>', 'There s something great about this photo.', '2013-01-29 19:49:58.000000', NULL, 1),
